export async function addMcpServer(agent, name, l, source = null) {
  const result = await readMcpConfig(agent)
  if (!result) return false
  const { configPath, data } = result
  setMcpServerEntry(data, agent, name, l)
  await mkdir(dirname(configPath), { recursive: true })
  await writeFile(configPath, `${JSON.stringify(data, null, 2)}\n`, 'utf-8')

  await addServerToMcpLock(name, {
    source: source || reconstructMcpSource(l, name),
    sourceType: l.sourceType,
    agents: [agent],
  })

  return true
}
